"""Build the isolated Contacts PWA bundle for its own web origin."""
from pathlib import Path
import html as html_lib
import json
from build_contacts_icon import build_icons
import qrcode

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "contacts-app"
OUT.mkdir(exist_ok=True)
PROFILES = [
    ("instagram", "Instagram", "@j.novaire", "https://www.instagram.com/j.novaire/"),
    ("whatsapp", "WhatsApp", "Message me", "https://wa.me/qr/FFFDDLXIDIN2I1"),
    ("telegram", "Telegram", "@JNovaire", "https://t.me/JNovaire"),
    ("linkedin", "LinkedIn", "Nolan James", "https://www.linkedin.com/in/nolanjamesfyfe/"),
]

cards = []
tabs = []
for index, (slug, label, subtitle, url) in enumerate(PROFILES):
    qr = qrcode.QRCode(error_correction=qrcode.constants.ERROR_CORRECT_M, box_size=10, border=4)
    qr.add_data(url)
    qr.make(fit=True)
    qr.make_image(fill_color="black", back_color="white").save(OUT / f"{slug}.png")
    safe_url = html_lib.escape(url, quote=True)
    selected = "true" if index == 0 else "false"
    cards.append(f'''<article class="social-card" id="card-{slug}" data-index="{index}" data-url="{safe_url}" aria-hidden="{str(index != 0).lower()}" aria-label="{label} business card">
<div class="card-sheen" aria-hidden="true"></div><p class="card-kicker">Nolan James · Digital Card</p><h2>{label}</h2><p class="handle">{html_lib.escape(subtitle)}</p>
<div class="qr-frame"><img src="/{slug}.png" alt="Scan to open my {label}" width="370" height="370"></div>
<div class="card-actions"><button class="share" type="button" data-action="share">Share card</button><button class="copy" type="button" data-action="copy">Copy link</button></div></article>''')
    tabs.append(f'<button class="platform-tab" type="button" role="tab" aria-selected="{selected}" aria-controls="card-{slug}" data-index="{index}">{label}</button>')

page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#09070d"><meta name="contacts-release" content="2026-10-25-v18"><title>Contacts · Nolan James</title><link rel="icon" href="/contacts-gold-192.png"><link rel="manifest" href="https://contacts.novairesignal.com/manifest.webmanifest?v=2"><link rel="apple-touch-icon" href="/contacts-gold-192.png"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Contacts"><meta name="apple-mobile-web-app-status-bar-style" content="black"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@300;500&display=swap" rel="stylesheet"><script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(console.error))}</script>
<style>
:root{color-scheme:dark;--gold:#b59662;--violet:#8d5cff;--ink:#f4efe8;--muted:#aaa3b0}*{box-sizing:border-box}html,body{margin:0;min-height:100%;overflow-x:hidden}body{background:#09070d;color:var(--ink);font-family:Arial,Helvetica,sans-serif;overscroll-behavior-x:none}body::before{content:"";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 26%,#51258940 0,transparent 35%),radial-gradient(ellipse at 50% 100%,#b5966217 0,transparent 52%),linear-gradient(135deg,#050407,#0e0815 54%,#050407);z-index:-2}body::after{content:"";position:fixed;inset:0;pointer-events:none;opacity:.18;background-image:linear-gradient(#fff1 1px,transparent 1px),linear-gradient(90deg,#fff1 1px,transparent 1px);background-size:60px 60px;mask-image:linear-gradient(to bottom,transparent,#000 35%,transparent);z-index:-1}
main{min-height:100svh;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;align-items:center;padding:max(18px,env(safe-area-inset-top)) 18px max(18px,env(safe-area-inset-bottom));isolation:isolate}.identity{text-align:center}.identity::before{content:"";display:block;width:42px;height:1px;margin:0 auto 13px;background:linear-gradient(90deg,transparent,var(--gold),transparent);box-shadow:0 0 15px #d5b477}.wordmark{font-family:'Cormorant Garamond',Georgia,serif;font-size:clamp(31px,5vw,46px);font-weight:300;line-height:1;text-transform:uppercase;letter-spacing:.2em;color:#f3eff8;margin:0;padding-left:.2em}.name{font-size:12px;letter-spacing:.24em;color:#aaa3ad;margin:8px 0 0;text-transform:uppercase}
.platforms{display:flex;gap:6px;max-width:620px;width:100%;margin:15px auto 2px;padding:5px;border:1px solid #ffffff13;border-radius:999px;background:#0c0910b8;backdrop-filter:blur(14px);overflow-x:auto;scrollbar-width:none}.platforms::-webkit-scrollbar{display:none}.platform-tab{flex:1 0 auto;border:0;border-radius:999px;padding:9px 12px;background:transparent;color:#8f8995;font:600 11px Arial;letter-spacing:.04em;cursor:pointer}.platform-tab[aria-selected="true"]{color:#fff4df;background:linear-gradient(135deg,#4d2a77,#1e152a);box-shadow:inset 0 0 0 1px #ad7cff4d,0 4px 18px #6d33bb36}.platform-tab:focus-visible,.nav-arrow:focus-visible,.card-actions button:focus-visible{outline:2px solid #d7b87b;outline-offset:3px}
.rack-stage{position:relative;width:min(100%,1180px);height:min(740px,calc(100svh - 170px));min-height:540px;margin:auto;perspective:1800px;touch-action:pan-y;user-select:none}.spindle{position:absolute;left:50%;top:3%;bottom:1%;width:5px;transform:translateX(-50%);border-radius:9px;background:linear-gradient(90deg,#08070a,#7a668d 43%,#241a2e 72%,#050407);box-shadow:0 0 0 1px #ffffff12,0 0 34px #9b5cff45;z-index:0}.spindle::before,.spindle::after{content:"";position:absolute;left:50%;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle at 35% 30%,#9f8daf,#2b2133 34%,#09070c 72%);border:1px solid #c7a6ee35;box-shadow:0 5px 22px #000}.spindle::before{top:-11px;width:31px;height:22px}.spindle::after{bottom:-14px;width:70px;height:26px}
.social-card{--x:0%;--z:0px;--r:0deg;--s:1;position:absolute;left:50%;top:50%;width:min(900px,calc(100vw - 180px));height:min(720px,calc(100svh - 190px));min-height:520px;padding:34px 56px 31px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;transform-style:preserve-3d;transform:translate3d(calc(-50% + var(--x)),-50%,var(--z)) rotateY(var(--r)) scale(var(--s));transform-origin:center;transition:transform .62s cubic-bezier(.2,.78,.2,1),opacity .35s ease,filter .35s ease;opacity:0;visibility:hidden;border:1px solid #b996dc55;border-radius:32px;background:linear-gradient(145deg,#22142f 0%,#130d1a 45%,#17100f 100%);box-shadow:inset 0 1px 0 #fff2,inset 0 -1px 0 #b5966233,0 28px 70px #000c,0 0 54px #7644bd2b;overflow:hidden;z-index:1}.social-card[data-position="active"]{opacity:1;visibility:visible;z-index:5}.social-card[data-position="prev"]{--x:-45%;--z:-190px;--r:80deg;--s:.92;opacity:.5;visibility:visible;filter:saturate(.45) brightness(.55);z-index:2}.social-card[data-position="next"]{--x:45%;--z:-190px;--r:-80deg;--s:.92;opacity:.5;visibility:visible;filter:saturate(.45) brightness(.55);z-index:2}.card-sheen{position:absolute;inset:0;pointer-events:none;background:linear-gradient(120deg,transparent 12%,#ffffff0d 32%,transparent 48%),radial-gradient(circle at 82% 8%,#9d6bed2b,transparent 28%)}.social-card::before{content:"";position:absolute;inset:10px;border:1px solid #d8b87920;border-radius:22px;pointer-events:none}.card-kicker{position:relative;margin:0 0 8px;color:#c5adcf;font-size:10px;letter-spacing:.2em;text-transform:uppercase}.social-card h2{position:relative;margin:0;font-family:'Cormorant Garamond',Georgia,serif;font-weight:500;font-size:clamp(34px,5vw,48px);line-height:1;color:#fff8ec}.handle{position:relative;margin:5px 0 16px;color:#bcb3c2;font-size:13px;letter-spacing:.08em}.qr-frame{position:relative;width:clamp(205px,29svh,265px);padding:7px;border-radius:15px;background:linear-gradient(145deg,#efd392,#8b6130 46%,#f5dfaa);box-shadow:0 0 0 1px #fae5b977,0 0 23px #d5aa5b64,0 0 56px #8149cd44}.qr-frame img{display:block;width:100%;height:auto;border-radius:8px;background:#fff;image-rendering:pixelated}.card-actions{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:9px;width:min(100%,420px);margin-top:20px}.card-actions button{min-height:44px;border-radius:999px;font:700 11px Arial;letter-spacing:.08em;text-transform:uppercase;cursor:pointer}.share{border:1px solid #d7b879;background:linear-gradient(135deg,#c7a86e,#876b3c);color:#100d10}.copy{border:1px solid #9d73ca66;background:#110c17;color:#e6dced}.nav-arrow{position:absolute;top:50%;width:52px;height:52px;margin-top:-26px;border:1px solid #b58cdb3b;border-radius:50%;background:#0d0912d9;color:#e8dbef;font-size:27px;line-height:1;cursor:pointer;z-index:9;backdrop-filter:blur(10px);box-shadow:0 9px 30px #0008}.nav-arrow:hover{border-color:#d2ad72;color:#f7e7c7}.nav-arrow.prev{left:0}.nav-arrow.next{right:0}
.rack-footer{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:16px;width:min(100%,560px);margin:3px auto 0;color:#89818e}.counter{justify-self:start;font:500 10px Arial;letter-spacing:.2em;text-transform:uppercase}.dots{display:flex;gap:8px}.dot{width:5px;height:5px;border-radius:50%;background:#5f5665;transition:transform .3s,background .3s}.dot.active{background:#d4b675;transform:scale(1.7);box-shadow:0 0 11px #d4b675}.gesture{justify-self:end;font-size:10px;letter-spacing:.08em}.status{position:fixed;left:50%;bottom:max(18px,env(safe-area-inset-bottom));translate:-50% 12px;z-index:30;margin:0;padding:10px 16px;border:1px solid #ae86d54d;border-radius:999px;background:#160f1ee8;color:#f5e9d7;font-size:12px;opacity:0;pointer-events:none;transition:opacity .2s,translate .2s;box-shadow:0 10px 30px #000a}.status.show{opacity:1;translate:-50% 0}
@media(max-width:650px){main{height:100svh;min-height:0;padding:8px 4px 7px}.identity::before{margin-bottom:7px}.wordmark{font-size:29px}.name{margin-top:5px}.platforms{margin:8px auto 1px}.platform-tab{padding:8px 10px}.rack-stage{width:100%;height:100%;min-height:0}.social-card{width:calc(100vw - 8px);height:calc(100% - 4px);min-height:0;padding:22px 28px 21px;border-radius:27px}.social-card[data-position="prev"]{--x:-51%;--z:-180px;--r:84deg;opacity:.4}.social-card[data-position="next"]{--x:51%;--z:-180px;--r:-84deg;opacity:.4}.nav-arrow{width:42px;height:42px;font-size:21px}.nav-arrow.prev{left:2px}.nav-arrow.next{right:2px}.card-kicker{margin-bottom:6px}.social-card h2{font-size:36px}.handle{margin-bottom:13px}.qr-frame{width:clamp(190px,28svh,245px)}.card-actions{width:min(100%,340px);margin-top:17px}.gesture{display:none}.rack-footer{grid-template-columns:1fr auto;margin-top:1px}.dots{justify-self:end}}
@media(max-height:800px) and (min-width:651px){main{height:100svh;min-height:0;padding-block:10px}.identity::before{margin-bottom:7px}.wordmark{font-size:32px}.name{margin-top:5px}.platforms{margin-top:8px}.rack-stage{height:100%;min-height:0}.social-card{height:calc(100% - 20px);min-height:0}.qr-frame{width:clamp(190px,27svh,245px)}}
@media(max-height:690px){.identity::before{margin-bottom:5px}.wordmark{font-size:27px}.name{margin-top:3px}.platforms{margin-top:6px}.social-card{padding-block:14px}.social-card h2{font-size:31px}.handle{margin-bottom:9px}.qr-frame{width:clamp(175px,27svh,220px)}.card-actions{margin-top:12px}.card-actions button{min-height:38px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.social-card,.dot,.status{transition:none!important}}
</style></head><body><main><header class="identity"><h1 class="wordmark">Novaire</h1><p class="name">Nolan James</p></header><nav class="platforms" role="tablist" aria-label="Choose a social card">__TABS__</nav><section class="rack-stage" aria-roledescription="carousel" aria-label="Social business cards"><div class="spindle" aria-hidden="true"></div><button class="nav-arrow prev" type="button" aria-label="Previous social card">‹</button>__CARDS__<button class="nav-arrow next" type="button" aria-label="Next social card">›</button></section><footer class="rack-footer"><span class="counter" aria-live="polite">Card 1 of 4</span><span class="dots" aria-hidden="true">__DOTS__</span><span class="gesture">Swipe or use ← →</span></footer></main><p class="status" role="status" aria-live="polite"></p>
<script>
(()=>{const cards=[...document.querySelectorAll('.social-card')],tabs=[...document.querySelectorAll('.platform-tab')],dots=[...document.querySelectorAll('.dot')],stage=document.querySelector('.rack-stage'),counter=document.querySelector('.counter'),status=document.querySelector('.status');let active=0,startX=0,startY=0,tracking=false,toastTimer;
const relative=(i)=>{let d=i-active;if(d>cards.length/2)d-=cards.length;if(d<-cards.length/2)d+=cards.length;return d};
function select(index,focusTab=false){active=(index+cards.length)%cards.length;cards.forEach((card,i)=>{const d=relative(i);card.dataset.position=d===0?'active':d===-1?'prev':d===1?'next':'hidden';card.setAttribute('aria-hidden',String(d!==0));card.inert=d!==0});tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===active));tab.tabIndex=i===active?0:-1});dots.forEach((dot,i)=>dot.classList.toggle('active',i===active));counter.textContent=`Card ${active+1} of ${cards.length}`;stage.dataset.active=String(active);if(focusTab)tabs[active].focus({preventScroll:true})}
function toast(message){clearTimeout(toastTimer);status.textContent=message;status.classList.add('show');toastTimer=setTimeout(()=>status.classList.remove('show'),1800)}
async function copyLink(url,label){try{await navigator.clipboard.writeText(url)}catch(_){const area=document.createElement('textarea');area.value=url;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();document.execCommand('copy');area.remove()}toast(`${label} link copied`)}
async function shareCard(card){const label=card.querySelector('h2').textContent,url=card.dataset.url;try{if(navigator.share){await navigator.share({title:`Nolan James · ${label}`,text:`Connect with Nolan James on ${label}`,url});toast(`${label} share opened`)}else await copyLink(url,label)}catch(error){if(error.name!=='AbortError')await copyLink(url,label)}}
tabs.forEach(tab=>tab.addEventListener('click',()=>select(Number(tab.dataset.index))));document.querySelector('.prev').addEventListener('click',()=>select(active-1));document.querySelector('.next').addEventListener('click',()=>select(active+1));cards.forEach(card=>card.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const label=card.querySelector('h2').textContent;if(button.dataset.action==='share')shareCard(card);else copyLink(card.dataset.url,label)}));
stage.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;tracking=true;startX=event.clientX;startY=event.clientY;try{stage.setPointerCapture?.(event.pointerId)}catch(_){}});const finishSwipe=event=>{if(!tracking)return;tracking=false;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.abs(dx)>48&&Math.abs(dx)>Math.abs(dy)*1.2)select(active+(dx<0?1:-1))};window.addEventListener('pointerup',finishSwipe);window.addEventListener('pointercancel',()=>tracking=false);document.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'){event.preventDefault();select(active-1,true)}if(event.key==='ArrowRight'){event.preventDefault();select(active+1,true)}if(event.key==='Home'){event.preventDefault();select(0,true)}if(event.key==='End'){event.preventDefault();select(cards.length-1,true)}});select(0)})();
</script></body></html>'''
html = page.replace("__TABS__", "".join(tabs)).replace("__CARDS__", "".join(cards)).replace("__DOTS__", "".join(f'<i class="dot{" active" if i == 0 else ""}"></i>' for i in range(len(PROFILES))))
(OUT / "index.html").write_text(html)
(OUT / "contacts").mkdir(exist_ok=True)
(OUT / "contacts" / "index.html").write_text(html)

manifest = {
    "id": "https://contacts.novairesignal.com/contacts-app",
    "name": "Contacts",
    "short_name": "Contacts",
    "description": "Instagram, WhatsApp, Telegram and LinkedIn QR codes for Nolan James",
    "start_url": "https://contacts.novairesignal.com/contacts/",
    "scope": "https://contacts.novairesignal.com/",
    "display": "standalone",
    "background_color": "#09070d",
    "theme_color": "#09070d",
    "icons": [
        {"src": "/contacts-gold-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"},
        {"src": "/contacts-gold-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"},
        {"src": "/contacts-gold-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"},
    ],
}
(OUT / "manifest.webmanifest").write_text(json.dumps(manifest, indent=2) + "\n")
assets = ["/", "/index.html", "/contacts/", "/contacts/index.html", "/linkedin.png", "/instagram.png", "/whatsapp.png", "/telegram.png", "/manifest.webmanifest", "/contacts-gold-192.png", "/contacts-gold-512.png", "/contacts-gold-maskable-512.png", "/favicon.ico"]
(OUT / "sw.js").write_text(f"""const CACHE='novaire-contacts-origin-v18';
const ASSETS={json.dumps(assets, separators=(',', ':'))};
self.cleanup=()=>caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('novaire-contacts-origin-')&&k!==CACHE).map(k=>caches.delete(k))));
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(self.cleanup().then(()=>self.clients.claim()).then(()=>self.clients.matchAll({{type:'window',includeUncontrolled:true}})).then(clients=>{{clients.forEach(client=>{{const url=new URL(client.url);if(url.origin===self.location.origin)client.navigate(client.url);}});}})));
self.addEventListener('fetch',event=>{{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!ASSETS.includes(url.pathname))return;event.waitUntil(self.cleanup());event.respondWith(fetch(event.request).then(response=>{{if(response.ok){{const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}}return response;}}).catch(()=>caches.match(event.request).then(cached=>cached||Response.error())));}});
""")
build_icons()
print("Built isolated contacts-app revolving card rack")
